import {
  directoryColumn2,
  pathColumn2
} from "./repository-cache-qnc92qwc.js";
import {
  Timestamps2
} from "./repository-cache-qfa1cgps.js";
import {
  ProjectTable2
} from "./repository-cache-rj3eygr5.js";

// src/session/sql.ts
import { sqliteTable, text, integer, index, primaryKey, real, uniqueIndex } from "drizzle-orm/sqlite-core";
import { sql } from "drizzle-orm";
var SessionTable2 = sqliteTable("session_v2", {
  id: text().$type().primaryKey(),
  project_id: text().$type().notNull().references(() => ProjectTable2.id, { onDelete: "cascade" }),
  workspace_id: text().$type(),
  parent_id: text().$type(),
  fork_session_id: text().$type(),
  fork_boundary: text({ mode: "json" }).$type(),
  slug: text().notNull(),
  directory: directoryColumn2().notNull(),
  path: pathColumn2(),
  title: text(),
  version: text().notNull(),
  share_url: text(),
  summary_additions: integer(),
  summary_deletions: integer(),
  summary_files: integer(),
  summary_diffs: text({ mode: "json" }).$type(),
  metadata: text({ mode: "json" }).$type(),
  cost: real().notNull().default(0),
  tokens_input: integer().notNull().default(0),
  tokens_output: integer().notNull().default(0),
  tokens_reasoning: integer().notNull().default(0),
  tokens_cache_read: integer().notNull().default(0),
  tokens_cache_write: integer().notNull().default(0),
  revert: text({ mode: "json" }).$type(),
  permission: text({ mode: "json" }).$type(),
  agent: text(),
  model: text({ mode: "json" }).$type(),
  ...Timestamps2,
  time_idle: integer(),
  time_viewed: integer(),
  idle_outcome: text().$type(),
  time_compacting: integer(),
  time_archived: integer(),
  time_suspended: integer(),
  resume_attempts: integer().notNull().default(0)
}, (table) => [
  index("session_v2_project_idx").on(table.project_id),
  index("session_v2_workspace_idx").on(table.workspace_id),
  index("session_v2_parent_idx").on(table.parent_id),
  index("session_v2_time_suspended_idx").on(table.time_suspended).where(sql`${table.time_suspended} is not null`)
]);
var SessionMessageTable2 = sqliteTable("session_message", {
  id: text().$type().primaryKey(),
  session_id: text().$type().notNull().references(() => SessionTable2.id, { onDelete: "cascade" }),
  type: text().$type().notNull(),
  seq: integer().notNull(),
  ...Timestamps2,
  data: text({ mode: "json" }).notNull().$type()
}, (table) => [
  uniqueIndex("session_message_session_seq_idx").on(table.session_id, table.seq),
  index("session_message_session_type_seq_idx").on(table.session_id, table.type, table.seq),
  index("session_message_session_time_created_id_idx").on(table.session_id, table.time_created, table.id),
  index("session_message_time_created_idx").on(table.time_created)
]);
var SessionPendingTable2 = sqliteTable("session_pending", {
  id: text().$type().primaryKey(),
  session_id: text().$type().notNull().references(() => SessionTable2.id, { onDelete: "cascade" }),
  type: text().$type().notNull(),
  data: text({ mode: "json" }).$type().notNull(),
  delivery: text().$type(),
  admitted_seq: integer().notNull(),
  time_created: integer().notNull().$default(() => Date.now())
}, (table) => [
  index("session_pending_session_delivery_seq_idx").on(table.session_id, table.delivery, table.admitted_seq),
  uniqueIndex("session_pending_session_compaction_idx").on(table.session_id).where(sql`${table.type} = 'compaction'`),
  uniqueIndex("session_pending_session_admitted_seq_idx").on(table.session_id, table.admitted_seq)
]);
var SessionInboxTable2 = sqliteTable("session_inbox", {
  id: text().$type().primaryKey(),
  session_id: text().$type().notNull().references(() => SessionTable2.id, { onDelete: "cascade" }),
  type: text().$type().notNull(),
  payload: text({ mode: "json" }).$type().notNull(),
  delivery: text().$type().notNull(),
  enqueued_seq: integer().notNull(),
  time_created: integer().notNull().$default(() => Date.now())
}, (table) => [
  index("session_inbox_session_delivery_seq_idx").on(table.session_id, table.delivery, table.enqueued_seq),
  uniqueIndex("session_inbox_session_enqueued_seq_idx").on(table.session_id, table.enqueued_seq)
]);
var InstructionEntryTable2 = sqliteTable("instruction_entry", {
  session_id: text().$type().notNull().references(() => SessionTable2.id, { onDelete: "cascade" }),
  key: text().notNull(),
  value: text({ mode: "json" }).$type(),
  removed: integer({ mode: "boolean" }).notNull().default(false),
  ...Timestamps2
}, (table) => [primaryKey({ columns: [table.session_id, table.key] })]);
var InstructionBlobTable2 = sqliteTable("instruction_blob", {
  hash: text().$type().primaryKey(),
  value: text({ mode: "json" }).$type()
});
var InstructionStateTable2 = sqliteTable("instruction_state", {
  session_id: text().$type().primaryKey().references(() => SessionTable2.id, { onDelete: "cascade" }),
  epoch_start: integer().notNull(),
  through_seq: integer().notNull(),
  initial_values: text({ mode: "json" }).notNull().$type(),
  current_values: text({ mode: "json" }).notNull().$type()
});

export { SessionTable2, SessionMessageTable2, SessionPendingTable2, SessionInboxTable2, InstructionEntryTable2, InstructionBlobTable2, InstructionStateTable2 };
